def execute(arguments):
    """
    延时暂停

    参数:
        arguments (dict): 包含以下字段
            - seconds (float): 暂停秒数，必填
            - message (str): 暂停期间的提示消息，可选

    返回:
        dict: 包含执行结果的字典
            - success (bool): 是否成功
            - seconds (float): 暂停的秒数
            - message (str): 提示消息
    """
    import time

    seconds = arguments.get("seconds", 0)
    message = arguments.get("message", "")

    if seconds <= 0:
        return {"success": False, "error": "暂停时间必须大于0"}

    if seconds > 300:
        return {"success": False, "error": "暂停时间不能超过300秒"}

    try:
        time.sleep(seconds)

        return {
            "success": True,
            "seconds": seconds,
            "message": message or f"已暂停 {seconds} 秒"
        }
    except Exception as e:
        return {"success": False, "error": f"暂停失败: {str(e)}"}
